import { HttpError } from "wasp/server";

export const getFolderContents = async (args: { folderId?: number | null }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;
  const folderId = args.folderId ? Number(args.folderId) : null;

  // Fetch folders inside current folder
  const folders = await context.entities.Folder.findMany({
    where: {
      userId,
      parentId: folderId,
    },
    orderBy: { name: "asc" },
  });

  // Fetch files inside current folder
  const files = await context.entities.File.findMany({
    where: {
      userId,
      folderId,
    },
    orderBy: { name: "asc" },
  });

  // Build breadcrumbs path
  const breadcrumbs: { id: number; name: string }[] = [];
  let currentId = folderId;
  while (currentId) {
    const f = await context.entities.Folder.findUnique({
      where: { id: currentId, userId },
    });
    if (!f) break;
    breadcrumbs.unshift({ id: f.id, name: f.name });
    currentId = f.parentId;
  }

  return {
    folders,
    files,
    breadcrumbs,
  };
};

export const getAccessLogs = async (args: any, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  const logs = await context.entities.AccessLog.findMany({
    where: {
      shareLink: {
        file: {
          userId,
        },
      },
    },
    include: {
      shareLink: {
        include: {
          file: true,
        },
      },
    },
    orderBy: { timestamp: "desc" },
  });

  return logs.map((log: any) => ({
    id: log.id,
    fileName: log.shareLink.file.name,
    timestamp: log.timestamp.toISOString(),
    ipAddress: log.ipAddress,
    userAgent: log.userAgent,
  }));
};

export const getShareLinkDetails = async (args: { linkId: string }, context: any) => {
  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: args.linkId },
    include: {
      file: true,
    },
  });

  if (!shareLink) {
    throw new HttpError(404, "Sharing link not found");
  }

  const isExpired = shareLink.expiresAt && new Date() > new Date(shareLink.expiresAt);

  return {
    id: shareLink.id,
    fileName: shareLink.file.name,
    isPasswordProtected: !!shareLink.password,
    isExpired: !!isExpired,
  };
};

import { HttpError } from "wasp/server";
import { RUN_ID } from "./config";

export const createFolder = async (
  args: { name: string; parentId?: number | null },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  if (!args.name || !args.name.trim()) {
    throw new HttpError(400, "Folder name is required");
  }

  let folderName = args.name.trim();
  if (!folderName.endsWith(`-${RUN_ID}`)) {
    folderName = `${folderName}-${RUN_ID}`;
  }

  const parentId = args.parentId ? Number(args.parentId) : null;

  // If parentId is specified, ensure it exists and belongs to the user
  if (parentId) {
    const parentFolder = await context.entities.Folder.findUnique({
      where: { id: parentId, userId },
    });
    if (!parentFolder) {
      throw new HttpError(400, "Parent folder not found");
    }
  }

  const newFolder = await context.entities.Folder.create({
    data: {
      name: folderName,
      parentId,
      userId,
    },
  });

  return newFolder;
};

export const createShareLink = async (
  args: { fileId: number; password?: string; expiresInMinutes?: number },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const userId = context.user.id;

  const file = await context.entities.File.findUnique({
    where: { id: Number(args.fileId), userId },
  });

  if (!file) {
    throw new HttpError(404, "File not found");
  }

  let expiresAt: Date | null = null;
  if (args.expiresInMinutes && args.expiresInMinutes > 0) {
    expiresAt = new Date(Date.now() + args.expiresInMinutes * 60 * 1000);
  }

  const shareLink = await context.entities.ShareLink.create({
    data: {
      fileId: file.id,
      password: args.password || null,
      expiresAt,
    },
  });

  return shareLink;
};

import multer from "multer";
import path from "path";
import fs from "fs";
import crypto from "crypto";

const UPLOADS_DIR = "/home/user/app/uploads/";

// Ensure uploads directory exists
if (!fs.existsSync(UPLOADS_DIR)) {
  fs.mkdirSync(UPLOADS_DIR, { recursive: true });
}

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, UPLOADS_DIR);
  },
  filename: (req, file, cb) => {
    const uniqueName = `${crypto.randomUUID()}${path.extname(file.originalname)}`;
    cb(null, uniqueName);
  },
});

const upload = multer({ storage }).single("file");

export const uploadFile = (req: any, res: any, context: any) => {
  if (!context.user) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  const userId = context.user.id;

  upload(req, res, async (err) => {
    if (err) {
      return res.status(500).json({ error: "Failed to upload file" });
    }

    if (!req.file) {
      return res.status(400).json({ error: "No file uploaded" });
    }

    const folderId = req.body.folderId ? Number(req.body.folderId) : null;

    if (folderId) {
      const folder = await context.entities.Folder.findUnique({
        where: { id: folderId, userId },
      });
      if (!folder) {
        return res.status(400).json({ error: "Folder not found" });
      }
    }

    const fileRecord = await context.entities.File.create({
      data: {
        name: req.file.originalname,
        filePath: req.file.path,
        folderId,
        userId,
      },
    });

    return res.json(fileRecord);
  });
};

export const downloadFile = async (req: any, res: any, context: any) => {
  const { linkId } = req.params;
  const password = req.query.password || null;

  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: linkId },
    include: {
      file: true,
    },
  });

  if (!shareLink) {
    return res.status(404).json({ error: "Sharing link not found" });
  }

  if (shareLink.expiresAt && new Date() > new Date(shareLink.expiresAt)) {
    return res.status(410).json({ error: "Sharing link has expired" });
  }

  if (shareLink.password && shareLink.password !== password) {
    return res.status(403).json({ error: "Incorrect password" });
  }

  const { file } = shareLink;
  if (!fs.existsSync(file.filePath)) {
    return res.status(404).json({ error: "File not found on server" });
  }

  const ipAddress = req.ip || req.headers["x-forwarded-for"] || "unknown";
  const userAgent = req.headers["user-agent"] || "unknown";

  await context.entities.AccessLog.create({
    data: {
      shareLinkId: shareLink.id,
      ipAddress: String(ipAddress),
      userAgent: String(userAgent),
    },
  });

  res.setHeader("Content-Disposition", `attachment; filename="${encodeURIComponent(file.name)}"`);
  res.sendFile(file.filePath);
};

import { app, page, route, query, action, api } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { FolderPage } from "./src/FolderPage" with { type: "ref" };
import { LogsPage } from "./src/LogsPage" with { type: "ref" };
import { SharePage } from "./src/SharePage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };

import { getFolderContents, getAccessLogs, getShareLinkDetails } from "./src/queries" with { type: "ref" };
import { createFolder, createShareLink } from "./src/actions" with { type: "ref" };
import { uploadFile, downloadFile } from "./src/apis" with { type: "ref" };

export default app({
  name: "app",
  wasp: { version: "^0.25.0" },
  title: "Wasp Drive",
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("FolderRoute", "/folder/:folderId", page(FolderPage, { authRequired: true })),
    route("LogsRoute", "/logs", page(LogsPage, { authRequired: true })),
    route("ShareRoute", "/share/:linkId", page(SharePage, { authRequired: false })),
    route("LoginRoute", "/login", page(LoginPage, { authRequired: false })),
    route("SignupRoute", "/signup", page(SignupPage, { authRequired: false })),

    query(getFolderContents, { entities: ["Folder", "File"] }),
    query(getAccessLogs, { entities: ["AccessLog", "ShareLink", "File"] }),
    query(getShareLinkDetails, { entities: ["ShareLink", "File"], auth: false }),

    action(createFolder, { entities: ["Folder"] }),
    action(createShareLink, { entities: ["ShareLink", "File"] }),

    api("POST", "/api/upload", uploadFile, { entities: ["File", "Folder"], auth: true }),
    api("GET", "/api/download/:linkId", downloadFile, { entities: ["ShareLink", "File", "AccessLog"], auth: false }),
  ],
});

import { useState } from "react";
import { Link, useNavigate } from "react-router";
import { login } from "wasp/client/auth";
import { RUN_ID } from "./config";
import "./Main.css";

export function LoginPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    let finalUsername = username.trim();
    if (!finalUsername) {
      setError("Username is required");
      return;
    }

    if (!finalUsername.endsWith(`-${RUN_ID}`)) {
      finalUsername = `${finalUsername}-${RUN_ID}`;
    }

    try {
      // Support both { username, password } and (username, password) signatures
      try {
        await login({ username: finalUsername, password });
      } catch (err: any) {
        if (err.message?.includes("is not a function") || err.message?.includes("undefined")) {
          await login(finalUsername, password);
        } else {
          throw err;
        }
      }
      navigate("/");
    } catch (err: any) {
      setError(err.message || "Invalid username or password");
    }
  };

  return (
    <div className="auth-container">
      <div className="auth-card">
        <h2>Login to Wasp Drive</h2>
        {error && <div className="error-message">{error}</div>}
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="username">Username</label>
            <input
              type="text"
              id="username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="Enter your username"
              required
            />
          </div>
          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter your password"
              required
            />
          </div>
          <button type="submit" className="auth-btn">
            Login
          </button>
        </form>
        <p className="auth-switch">
          Don't have an account? <Link to="/signup">Sign up</Link>
        </p>
      </div>
    </div>
  );
}

